  file.value=loaded;configure();notice.value=loaded.sheets.length?`Hoja "${name}" cargada: ${loaded.sheets[0]?.rows.length??0} filas con datos.`:`Hoja "${name}" vacía. No hay contratos ni saldos del Excel para revisar.`;
