const excelHints=computed(()=>groupExcelRowsByContract(rows.value));
/** Nombre legible del color real (hex) sin inventar significado comercial — solo para que la persona lo reconozca ("celeste", "verde", etc.), nunca para decidir modalidad. */
function colorLabel(hex:string):string{
 const names:Record<string,string>={'00FFFF':'celeste/cian','00FF00':'verde','FFFF00':'amarillo','FF9900':'naranja','FFFFFF':'blanco','0000FF':'azul'};
 return names[hex.toUpperCase()]??('#'+hex);
}
function excelColorSummary(hint:ExcelContractHint|null):string{
 if(!hint)return'';
 const entries=Object.entries(hint.colorCounts).sort((a,b)=>b[1]-a[1]);
 if(!entries.length)return'sin color';
 return entries.map(([hex,count])=>`${colorLabel(hex)} (${count})`).join(' · ');
}
