  if(scope!==openingRevision)return;
  try{
   await rpc('finance_set_billing_terms',{p_operation_id:crypto.randomUUID(),p_contract_id:r.contractId,p_modality:d.modality,p_billing_day:d.day,p_grace_days:d.modality==='adelantado'?d.grace:0,p_reason:termsReason.value.trim()});
   ok.push(r.contractId);
  }catch(e){failed.push({contractId:r.contractId,contractNumber:r.contractNumber,error:String(e)});}
 }
 if(scope!==openingRevision)return;
 termsSelected.value=new Set();
 termsBusy.value=false;
 await openingLoadPreview();
 if(scope!==openingRevision)return;
 termsResults.value={ok,failed};
 emit('changed');
}
watch([openingMode,openingZone],resetOpening,{flush:'sync'});
watch(openingSearch,()=>{searchRevision++;openingResults.value=[];},{flush:'sync'});
watch(()=>mapping.value.zoneId,()=>{resetImport();if(openingMode.value==='zone')openingZone.value=mapping.value.zoneId;},{flush:'sync'});
onBeforeUnmount(()=>{uploadRevision++;sourceRevision++;openingRevision++;previewRevision++;searchRevision++;comparisonRevision++;});
async function openingSearchContracts(){if(!openingSearch.value.trim())return;const scope=openingRevision,request=++searchRevision;openingError.value='';try{const data=await rpc<{id:string;contract_number:string;client_code:string;customer:string}[]>('finance_search_contracts',{p_search:openingSearch.value});if(scope===openingRevision&&request===searchRevision)openingResults.value=data??[];}catch(e){if(scope===openingRevision&&request===searchRevision)openingError.value=String(e);}}
function openingPick(c:{id:string;contract_number:string;client_code:string;customer:string}){if(!openingPicked.value.some(p=>p.id===c.id))openingPicked.value.push({id:c.id,contract_number:c.contract_number,customer:c.customer});}
function openingUnpick(id:string){openingPicked.value=openingPicked.value.filter(p=>p.id!==id);}
async function openingLoadPreview(){const scope=openingRevision,request=++previewRevision;openingBusy.value=true;openingError.value='';openingOutcome.value=null;try{
 const args=openingMode.value==='zone'?{p_zone:openingZone.value||null,p_contract_ids:null}:{p_zone:null,p_contract_ids:openingPicked.value.map(p=>p.id)};
 if(openingMode.value==='zone'&&!openingZone.value)throw Error('Selecciona la PON a abrir.');
 if(openingMode.value==='individual'&&!openingPicked.value.length)throw Error('Agrega al menos un contrato exacto.');
 const data=await rpc<{rows:OpeningRow[]}>('finance_opening_balance_preview',args);
 if(scope!==openingRevision||request!==previewRevision)return;
 openingRows.value=data.rows??[];
 const drafts:Record<string,OpeningDraft>={};
 const corrections:Record<string,{date:string;reason:string}>={};
 for(const r of openingRows.value){drafts[r.contractId]=openingDrafts.value[r.contractId]??{mode:'direct',anchorDate:'',receivedDate:'',months:'1',promo3plus1:false,debtAmount:'0',debtDueDate:'',creditAmount:'0',rowReason:''};if(r.alreadyAnchored)corrections[r.contractId]=openingCorrection.value[r.contractId]??{date:'',reason:''};}
 openingDrafts.value=drafts;openingCorrection.value=corrections;openingBatchId.value='';openingReviewOpen.value=false;openingSelected.value=new Set();
 openingNotice.value=`${openingRows.value.length} contratos en vista previa. Ningún dato se escribió todavía.`;
 const newTermsDrafts:Record<string,TermsDraft>={};
 for(const r of openingRows.value)if(!r.isCourtesy&&!r.billingTermsConfirmed)newTermsDrafts[r.contractId]=termsDrafts.value[r.contractId]??{modality:null,day:r.legacyBillingDay??1,grace:7};
 termsDrafts.value=newTermsDrafts;termsSelected.value=new Set();termsResults.value=null;
}catch(e){if(scope===openingRevision&&request===previewRevision)openingError.value=String(e);}finally{if(scope===openingRevision&&request===previewRevision)openingBusy.value=false;}}
/** Aplica, solo a los que todavía no tienen modalidad elegida a mano, la sugerencia de color del Excel ya cargado — explícito (un botón), nunca automático al cargar. Cada fila sigue siendo editable/corregible antes de confirmar. */
function termsApplySuggestions(){for(const r of termsCandidates.value){const d=termsDrafts.value[r.contractId];if(!d||d.modality)continue;const s=termsSuggestion(r);if(s.confidence==='clear')termsDrafts.value[r.contractId]={...d,modality:s.modality};}}
function openingIssues(r:OpeningRow):string[]{const out:string[]=[];if(openingBlocked(r))return out;const d=openingDrafts.value[r.contractId];if(!d)return['Sin datos'];
 if(d.mode==='direct'){if(!/^\d{4}-\d{2}-\d{2}$/.test(d.anchorDate)||d.anchorDate>limaDate())out.push('Fecha ancla (último período cubierto) requerida, no futura');}
 else{if(!/^\d{4}-\d{2}-\d{2}$/.test(d.receivedDate)||d.receivedDate>limaDate())out.push('Fecha real de recepción del dinero requerida, no futura');const cycles=openingAdvanceCycles(d);if(!cycles)out.push('Selecciona meses de adelanto (1-12) o marca la promoción 3+1');const coverage=openingCoverageThrough(r,d);if(cycles&&!coverage)out.push('No se pudo calcular la cobertura pagada (verifica el día de facturación del contrato)');}
 try{if(d.debtAmount&&penCents(d.debtAmount)>0&&!d.debtDueDate)out.push('Vencimiento de la deuda inicial requerido');}catch{out.push('Importe de deuda inválido');}try{if(d.creditAmount&&penCents(d.creditAmount)<0)out.push('Saldo a favor inválido');}catch{out.push('Saldo a favor inválido');}return out;}
const openingEligible=computed(()=>openingRows.value.filter(r=>!openingBlocked(r))),openingReady=computed(()=>openingEligible.value.filter(r=>openingSelected.value.has(r.contractId)&&!openingIssues(r).length));
function openingReview(){openingError.value='';try{const name=openingLabel.value.trim();if(name.length<3||name.length>120)throw Error('Nombre de lote inválido.');if(!openingDate.value||openingDate.value>limaDate())throw Error('Fecha de apertura inválida.');if(openingReason.value.trim().length<10)throw Error('Motivo del lote requerido (mínimo 10 caracteres).');if(!openingReady.value.length)throw Error('No hay contratos listos para abrir.');openingBatchId.value=crypto.randomUUID();openingReviewedSnapshot.value=JSON.stringify([openingReady.value.map(r=>r.contractId),openingDrafts.value,openingLabel.value,openingDate.value,openingReason.value]);openingReviewOpen.value=true;}catch(e){openingError.value=String(e);}}
async function openingCommit(){if(openingBusy.value||!openingReviewOpen.value)return;const scope=openingRevision;openingBusy.value=true;openingError.value='';try{
 if(openingReviewedSnapshot.value!==JSON.stringify([openingReady.value.map(r=>r.contractId),openingDrafts.value,openingLabel.value,openingDate.value,openingReason.value])){openingReviewOpen.value=false;throw Error('La vista revisada cambió. Vuelve a revisar el lote.');}
 const rows=openingReady.value.map(r=>{const d=openingDrafts.value[r.contractId]!;const debt=penCents(d.debtAmount||'0');const base={contractId:r.contractId,debtAmount:debt/100,debtDueDate:debt>0?d.debtDueDate:null,creditAmount:penCents(d.creditAmount||'0')/100,rowReason:d.rowReason.trim()||undefined};return d.mode==='advance'?{...base,receivedDate:d.receivedDate,coverageThroughDate:openingCoverageThrough(r,d),promo3plus1:d.promo3plus1}:{...base,anchorDate:d.anchorDate};});
 const result=await rpc<Record<string,unknown>>('finance_opening_balance_commit',{p_batch_id:openingBatchId.value,p_label:openingLabel.value,p_opening_date:openingDate.value,p_reason:openingReason.value,p_rows:rows});
 if(scope!==openingRevision)return;
 openingOutcome.value=result;openingReviewOpen.value=false;openingNotice.value='Apertura confirmada. No se registró ningún pago; el ancla y el saldo inicial quedan separados de la recaudación real. Vuelve a cargar la vista previa para ver el estado actualizado.';emit('changed');
}catch(e){if(scope===openingRevision)openingError.value=String(e);}finally{if(scope===openingRevision)openingBusy.value=false;}}
async function openingCorrect(r:OpeningRow){const c=openingCorrection.value[r.contractId];if(!c)return;const scope=openingRevision;openingError.value='';try{if(!c.date||c.date>limaDate())throw Error('Fecha de corrección inválida.');if(c.reason.trim().length<5)throw Error('Motivo de corrección requerido.');await rpc('finance_correct_opening_anchor',{p_operation_id:crypto.randomUUID(),p_contract_id:r.contractId,p_new_anchor_date:c.date,p_reason:c.reason});if(scope!==openingRevision)return;delete openingCorrection.value[r.contractId];openingNotice.value=`Ancla corregida para ${r.contractNumber}.`;await openingLoadPreview();}catch(e){if(scope===openingRevision)openingError.value=String(e);}}
function exportReview(){const safe=(v:unknown)=>'"'+String(v??'').replace(/^\s*[=+@-]/,"'").replaceAll('"','""')+'"';const data=[['Hoja','Fila','Columna','Cintillo','Contrato fuente','Tipo','Periodo','Importe fuente','Importe revisado','Estado / diferencias'],...rows.value.map(r=>[r.sheet,r.row,r.column,r.subscriber,r.contractCode,kinds[r.kind],r.period,r.sourceAmount,r.amount,issues(r).join(' / ')||'Verificado'])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='conciliacion-vista-previa.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section class="finance-reconciliation"><header class="finance-table-tools"><h2>Conciliación desde Google Sheets</h2><button class="btn-ghost" :disabled="!rows.length" @click="exportReview">Exportar revisión (CSV)</button></header><p class="finance-warning"><b>Sin habilitación productiva</b><span>Archivos procesados en memoria. No se sube Excel ni se activan cortes. La muestra real sigue pendiente de validación.</span></p><p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="notice" role="status" class="finance-notice">{{notice}}</p>
 <article v-if="termsCandidates.length" class="finance-panel"><h3>0. Confirmar condiciones comerciales por lote (paso previo a la apertura)</h3>
 <p class="finance-help">Un contrato necesita su modalidad y día de pago confirmados antes de poder incorporarse. El color del Excel (celeste/cian/azul = adelantado con 7 días de prórroga, verde = pago cumplido sin prórroga) es solo una <b>sugerencia</b> — revísala y corrígela si hace falta, nunca se aplica sola. El día de pago ya registrado en SmartRayco (si existe) también se sugiere, editable.</p>
 <p v-if="termsError" role="alert" class="finance-error">{{termsError}}</p>
 <div v-if="termsResults" class="reconcile-hint">Confirmados: {{termsResults.ok.length}}. <template v-if="termsResults.failed.length">Con error (sin tocar los demás): {{termsResults.failed.map(f=>f.contractNumber).join(', ')}}.</template></div>
 <div class="finance-filters"><button class="btn-ghost" @click="termsApplySuggestions">Aplicar sugerencias del Excel (color + día)</button><button class="btn-ghost" @click="termsSelectAllSuggested">Seleccionar los que ya quedaron sin pendientes</button><button class="btn-ghost" @click="termsSelectNone">Deseleccionar todos</button></div>
 <div class="reconcile-rows"><details v-for="r in termsCandidates" :key="r.contractId" class="reconcile-row" :open="!!termsIssues(r).length"><summary class="reconcile-row-head"><input type="checkbox" :checked="termsSelected.has(r.contractId)" :aria-label="'Seleccionar condiciones de '+r.contractNumber" @click.stop="termsToggle(r.contractId)"><b>{{r.contractNumber}} · {{r.clientCode}}</b><span>{{r.customer}}</span><span>Mensualidad {{formatPen(r.monthlyFee)}}</span></summary>
  <p v-if="excelHint(r)" class="reconcile-hint">Excel ({{pickedSheetName}}): color predominante {{excelColorSummary(excelHint(r))}} → sugerencia: <b>{{termsSuggestion(r).modality==='adelantado'?'Pago adelantado':termsSuggestion(r).modality==='cumplido'?'Pago cumplido':'No concluyente, elige tú'}}</b>.</p>
  <p v-else class="reconcile-hint">Sin coincidencia en el Excel cargado — sin sugerencia de color, elige la modalidad manualmente.</p>
  <div v-if="termsDrafts[r.contractId]" class="reconcile-row-fields">
   <label>Modalidad<select v-model="termsDrafts[r.contractId].modality"><option :value="null">Seleccionar</option><option value="adelantado">Pago adelantado (con prórroga)</option><option value="cumplido">Pago cumplido (sin prórroga)</option></select></label>
   <label>Día de pago (1-31){{r.legacyBillingDay?' · sugerido: '+r.legacyBillingDay:''}}<input v-model.number="termsDrafts[r.contractId].day" type="number" min="1" max="31"></label>
   <label v-if="termsDrafts[r.contractId].modality==='adelantado'">Días de prórroga<input v-model.number="termsDrafts[r.contractId].grace" type="number" min="0" max="60"></label>
  </div>
  <small :class="termsIssues(r).length?'reconcile-pending':'reconcile-valid'">{{termsIssues(r).join(' · ')||'Listo para confirmar'}}</small>
 </details></div>
 <div class="finance-filters"><label>Motivo del lote (igual para todos los seleccionados)<input v-model="termsReason" maxlength="500" minlength="5" placeholder="Ej. Conciliación PON — condiciones vistas en Fibra Rayco.xlsx, corte 2026-11-26"></label></div>
 <button class="btn-primary" :disabled="termsBusy||!termsReady.length" @click="termsConfirmSelected">Confirmar condiciones seleccionadas ({{termsReady.length}} contratos)</button>
 </article>
 <article class="finance-panel"><h3>Apertura financiera real (saldo inicial y ancla de ciclo)</h3><p class="finance-help">Para contratos ya operando cuyo historial vive en Excel (no en SmartRayco). Registra el último período realmente cubierto y, si corresponde, la deuda pendiente a hoy o un saldo a favor existente — nunca un pago de caja. Reutilizable para cualquier PON, no exclusivo de un piloto.</p>
 <p v-if="openingError" role="alert" class="finance-error">{{openingError}}</p><p v-if="openingNotice" role="status" class="finance-notice">{{openingNotice}}</p>
 <div class="finance-filters"><label>Selección<select v-model="openingMode"><option value="zone">Por PON completa</option><option value="individual">Contratos exactos</option></select></label>
 <label v-if="openingMode==='zone'">PON a abrir<select v-model="openingZone" aria-label="PON a abrir"><option value="">Seleccionar</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label>
 <button class="btn-secondary" :disabled="openingBusy" @click="openingLoadPreview">Cargar vista previa</button></div>
 <template v-if="openingMode==='individual'"><div class="finance-filters"><label>Buscar por nombre, DNI o cintillo<input v-model="openingSearch" @keyup.enter="openingSearchContracts"></label><button class="btn-ghost" :disabled="openingBusy" @click="openingSearchContracts">Buscar</button></div>
 <div v-if="openingResults.length" class="reconcile-promo"><label v-for="c in openingResults" :key="c.id"><button class="btn-ghost" @click="openingPick(c)">+ {{c.contract_number}} · {{c.client_code}} · {{c.customer}}</button></label></div>
 <p v-if="openingPicked.length">Seleccionados: <span v-for="p in openingPicked" :key="p.id">{{p.contract_number}} ({{p.customer}}) <button class="btn-ghost" @click="openingUnpick(p.id)">quitar</button> </span></p></template>
 <template v-if="openingRows.length">
 <div class="reconcile-progress"><b>Avance de esta PON:</b> {{openingProgress.total}} contratos · <span class="reconcile-valid">{{openingProgress.alreadyDone}} ya conciliados</span> · <span class="reconcile-valid">{{openingProgress.readyNow}} listos para confirmar ahora</span> · <span class="reconcile-pending">{{openingProgress.observed}} observados/pendientes</span> · {{openingProgress.courtesy}} cortesía (protegidos, sin deuda)</div>
 <div class="finance-filters"><button class="btn-ghost" @click="openingSelectAllEligible">Seleccionar todos los elegibles ({{openingEligible.length}})</button><button class="btn-ghost" @click="openingSelectNone">Deseleccionar todos</button></div>
 <h4>Contratos correctos — listos para revisar e incorporar ({{openingEligible.length}})</h4>
 <p class="finance-help">Los que no tienen ninguna diferencia marcada abajo pueden quedar seleccionados y confirmarse por lote sin necesidad de abrir cada uno; los que sí tienen una diferencia se muestran abiertos para que los mires primero.</p>
 <div class="reconcile-rows"><details v-for="r in openingEligible" :key="r.contractId" class="reconcile-row" :open="openingHasDifference(r)"><summary class="reconcile-row-head"><input type="checkbox" :checked="openingSelected.has(r.contractId)" :aria-label="'Seleccionar '+r.contractNumber" @click.stop="openingToggle(r.contractId)"><b>{{r.contractNumber}} · {{r.clientCode}}</b><span>{{r.customer}}</span><span>Mensualidad {{formatPen(r.monthlyFee)}} · {{r.billingModality?`${r.billingModality} (confirmada)`:'Modalidad sin confirmar'}}</span><span v-if="!r.billingDay&&r.legacyBillingDay">Día de pago sugerido: {{r.legacyBillingDay}} (sin confirmar todavía)</span><span v-if="openingHasDifference(r)" class="reconcile-pending">⚠ revisar</span></summary>
 <p v-if="r.warnings.length" class="reconcile-hint">{{r.warnings.join(' · ')}}</p>
 <p v-if="excelHint(r)" class="reconcile-hint">Excel ({{pickedSheetName}}): mensualidad vista {{excelHint(r)!.fee.join(' / ')||'sin dato'}} · último período con dato <b>{{excelHint(r)!.lastPeriod||'sin dato'}}</b> ({{excelHint(r)!.periodsWithAmount}} período(s) con importe) · color visto en esa fila: {{excelColorSummary(excelHint(r))}} — informativo, nunca decide si es adelantado o cumplido, eso lo elige la persona abajo. Dato del Excel, no se aplica solo.</p>
 <p v-if="excelFeeDiffers(r)" class="reconcile-hint" role="alert">Diferencia de mensualidad: el Excel muestra <b>{{excelFeeDiffers(r)}}</b> y el contrato tiene registrado {{formatPen(r.monthlyFee)}}. No se cambia la tarifa aquí — verifica cuál es correcta; una vez que este contrato quede incorporado (abajo), podrás corregirla con "Corregir mensualidad" (auditada, igual que el ancla) desde su ficha.</p>
 <p v-else-if="file" class="reconcile-hint">Sin coincidencia en la hoja "{{pickedSheetName}}" por cintillo ni número de contrato — revisar manualmente si corresponde a otra fila u hoja.</p>
 <div class="reconcile-row-fields"><label>Tipo de apertura<select v-model="openingDrafts[r.contractId].mode"><option value="direct">Fecha exacta (ancla directa)</option><option value="advance">Adelanto verificado (meses ya pagados)</option></select></label></div>
 <div v-if="openingDrafts[r.contractId].mode==='direct'" class="reconcile-row-fields"><label>Último período cubierto (ancla)<input v-model="openingDrafts[r.contractId].anchorDate" type="date"></label><label>Deuda inicial pendiente PEN<input v-model="openingDrafts[r.contractId].debtAmount" inputmode="decimal"></label><label>Vencimiento de esa deuda<input v-model="openingDrafts[r.contractId].debtDueDate" type="date"></label><label>Saldo a favor existente PEN<input v-model="openingDrafts[r.contractId].creditAmount" inputmode="decimal"></label><label>Motivo específico (opcional)<input v-model="openingDrafts[r.contractId].rowReason" maxlength="500"></label></div>
 <template v-else><p class="finance-help">Diferencia explícita: fecha real de recepción del dinero (siempre verificable, nunca futura) vs. período de servicio ya pagado y cobertura resultante — nunca se teclea una fecha de cobertura libre, se calcula a partir de los meses de adelanto reales del contrato.</p>
 <div class="reconcile-row-fields"><label>Fecha real de recepción del dinero<input v-model="openingDrafts[r.contractId].receivedDate" type="date"></label><label>Meses de adelanto<select v-model="openingDrafts[r.contractId].months" :disabled="openingDrafts[r.contractId].promo3plus1"><option v-for="n in [1,2,3,6,12]" :key="n" :value="String(n)">{{n}} {{n===1?'mes':'meses'}}</option></select></label><label class="reconcile-attest"><input v-model="openingDrafts[r.contractId].promo3plus1" type="checkbox">Promoción 3+1 (paga 3 meses, el 4.º es gratis — cubre exactamente 4 ciclos)</label><label>Deuda inicial pendiente PEN<input v-model="openingDrafts[r.contractId].debtAmount" inputmode="decimal"></label><label>Vencimiento de esa deuda<input v-model="openingDrafts[r.contractId].debtDueDate" type="date"></label><label>Saldo a favor existente PEN (dinero no aplicado a ningún período)<input v-model="openingDrafts[r.contractId].creditAmount" inputmode="decimal"></label><label>Motivo específico (opcional)<input v-model="openingDrafts[r.contractId].rowReason" maxlength="500"></label></div>
 <p v-if="openingCoverageThrough(r,openingDrafts[r.contractId])" class="reconcile-hint">Período de servicio pagado hasta <b>{{openingCoverageThrough(r,openingDrafts[r.contractId])}}</b>{{openingNextDuePreview(r,openingDrafts[r.contractId])?` · próximo vencimiento ${openingNextDuePreview(r,openingDrafts[r.contractId])!.nextDue} · fin de prórroga ${openingNextDuePreview(r,openingDrafts[r.contractId])!.graceEnd}`:''}} — calculado a partir de la fecha real de recepción, nunca inventado.<template v-if="openingNextDuePreview(r,openingDrafts[r.contractId])&&!openingNextDuePreview(r,openingDrafts[r.contractId])!.confirmed"> Usa el día de pago <b>sugerido</b> ({{effectiveBillingDay(r).day}}), todavía sin confirmar — confírmalo primero en Cobranzas → Confirmar condiciones para que deje de ser una sugerencia.</template></p></template>
 <small :class="openingIssues(r).length?'reconcile-pending':'reconcile-valid'">{{openingIssues(r).join(' · ')||'Listo para incorporar'}}</small></details></div>
 <details class="reconcile-observed-group"><summary><b>Observados / cortesía / ya conciliados ({{openingObserved.length}})</b> — no bloquean a los demás, revisar en lenguaje sencillo por qué cada uno está aquí</summary>
 <div class="reconcile-rows"><details v-for="r in openingObserved" :key="r.contractId" class="reconcile-row"><summary class="reconcile-row-head"><b>{{r.contractNumber}} · {{r.clientCode}}</b><span>{{r.customer}}</span><span>Mensualidad {{formatPen(r.monthlyFee)}}</span></summary>
 <p class="reconcile-hint">{{r.isCourtesy?'Es un servicio de cortesía: no necesita incorporarse, nunca se le genera deuda.':!r.billingTermsConfirmed?'Todavía no tiene confirmada su modalidad comercial (adelantado/cumplido) ni su día de pago — confírmalos primero en Cobranzas → Confirmar condiciones.':r.alreadyOpened?'Ya tiene un saldo inicial registrado — no hace falta repetirlo.':r.alreadyAnchored?'Ya tiene un ancla de apertura confirmada: '+r.existingAnchorDate+'.':'Sin motivo identificado automáticamente — revisar manualmente.'}}</p>
 <p v-if="excelHint(r)" class="reconcile-hint">Excel ({{pickedSheetName}}): mensualidad vista {{excelHint(r)!.fee.join(' / ')||'sin dato'}} · último período con dato {{excelHint(r)!.lastPeriod||'sin dato'}}.</p>
 <p v-else-if="file" class="reconcile-hint">Sin coincidencia en la hoja "{{pickedSheetName}}" por cintillo ni número de contrato.</p>
 <p v-if="r.alreadyAnchored&&auth.role==='SUPERADMIN'&&openingCorrection[r.contractId]"><input v-model="openingCorrection[r.contractId].date" type="date" aria-label="Nueva fecha ancla"><input v-model="openingCorrection[r.contractId].reason" placeholder="Motivo de la corrección" maxlength="500"><button class="btn-ghost" @click="openingCorrect(r)">Corregir ancla (auditado)</button></p>
 </details></div></details>
 <div class="finance-filters"><label>Nombre del lote<input v-model="openingLabel" maxlength="120"></label><label>Fecha de apertura (corte real)<input v-model="openingDate" type="date"></label><label>Motivo del lote<input v-model="openingReason" maxlength="500" minlength="10"></label></div>
 <button class="btn-primary" :disabled="openingBusy||!openingReady.length" @click="openingReview">Revisar apertura ({{openingReady.length}} contratos)</button>
 <div v-if="openingReviewOpen" class="reconcile-final"><h3>Confirmación humana · {{openingReady.length}} contratos</h3><p>No se registra ningún pago ni se genera caja. El saldo inicial y el ancla quedan separados de la recaudación real, auditados y no se pueden duplicar.</p><button class="btn-secondary" :disabled="openingBusy" @click="openingReviewOpen=false">Volver a revisión</button><button class="btn-primary" :disabled="openingBusy" @click="openingCommit">Confirmar apertura real</button></div>
 <div v-if="openingOutcome" class="reconcile-result"><h3>Resultado de la apertura</h3><pre>{{JSON.stringify(openingOutcome,null,2)}}</pre></div></template></article>
 <article class="finance-panel"><h3>1. Archivo y hojas por PON</h3><p class="finance-help">El archivo real tiene una hoja por PON (y alguna hoja extra). Se procesa <b>una sola hoja a la vez</b> — nunca el libro completo — para que ninguna PON agote el tope de 10&nbsp;000 filas por culpa de las demás.</p><label class="reconcile-upload">Excel exportado desde Google Sheets<input type="file" accept=".xlsx" :disabled="busy" aria-label="Archivo Excel de conciliación" @change="upload"></label>
 <div v-if="availableSheetNames.length" class="finance-filters"><label>Hoja / PON del archivo<select v-model="pickedSheetName" aria-label="Hoja de conciliación" :disabled="busy" @change="loadSheet"><option value="">Seleccionar hoja</option><option v-for="name in availableSheetNames" :key="name" :value="name">{{name}}</option></select></label><label>PON verificada<select v-model="mapping.zoneId" aria-label="PON de conciliación"><option value="">Seleccionar relación real</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label></div>
 <template v-if="file"><p>Hoja cargada: <b>{{pickedSheetName}}</b> · {{file.excludedColumns}} columnas técnicas excluidas · {{file.blankCells}} celdas vacías, sin interpretación de deuda.</p><div class="finance-filters"><label>Organización<select v-model="mapping.mode"><option value="matrix">Mensualidades en columnas</option><option value="ledger">Operaciones en filas</option></select></label><label v-if="mapping.mode==='matrix'">Año real de la hoja<input v-model="year" type="number" min="2020" max="2100" aria-label="Año del Excel"></label></div>
 <div class="reconcile-mapping"><label v-for="[key,title] in [['contract','Contrato'],['subscriber','Cintillo / abonado'],['customer','Cliente'],['fee','Mensualidad fuente'],['date','Fecha real del cobro'],['method','Medio de pago'],['observation','Observaciones locales'],['reference','Operación / recibo fuente']]" :key="key">{{title}}<select v-model="(mapping as unknown as Record<string,unknown>)[key!]"><option value="">No disponible</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.column}} · {{h.label}}</option></select></label></div>
 <div v-if="mapping.mode==='matrix'" class="reconcile-months"><label v-for="h in sheet?.headers.filter(h=>monthCandidate(h.label))" :key="h.column"><input v-model="monthColumns" type="checkbox" :value="h.column">{{h.label}}</label></div><div v-else class="finance-filters"><label>Importe<select v-model="mapping.amountColumn"><option value="">Seleccionar</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.label}}</option></select></label><label>Período de servicio (AAAA-MM)<select v-model="mapping.periodColumn"><option value="">Sin asignación</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.label}}</option></select></label></div>
 <label class="reconcile-attest"><input v-model="confirmedMapping" type="checkbox">Verifiqué qué representan las columnas elegidas. No trataré colores ni vacíos como pagos o deuda; cada operación se revisará antes de confirmar.</label><button class="btn-secondary" :disabled="busy" @click="addSheet">Añadir hoja a vista previa</button></template></article>
 <template v-if="rows.length"><article class="finance-panel"><h3>2. Identificar y revisar operaciones</h3><div class="finance-filters"><label>Responsable original confirmado<select v-model="originalCollector" aria-label="Cobrador original"><option value="">Sin identificar</option><option v-for="c in context?.collectors" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="btn-ghost" @click="applyCollector">Aplicar responsable a esta página</button><button class="btn-secondary" :disabled="busy" @click="compare">Comparar página con SmartRayco</button><button class="btn-ghost" :disabled="busy" @click="resolveExact">Resolver coincidencias exactas</button></div><p class="finance-help">Solo coincidencias verificables. Un nombre igual no autoriza elegir el primer contrato. Las mensualidades diferentes requieren resolver el cargo histórico; no se cambia el plan ni la tarifa automáticamente.</p><div class="reconcile-rows"><details v-for="r in visible" :key="r.key" class="reconcile-row"><summary class="reconcile-row-head"><b>{{r.sheet}} · {{r.row}}:{{r.column}}</b><span>{{r.customer}} · {{r.subscriber||r.contractCode||'Sin identificador'}}</span><span>{{r.period||'Período sin identificar'}}</span></summary><p class="finance-help">Celda fuente (solo local): {{sourceCell(r)}} / Importe fuente verificable: {{r.sourceAmount||'No identificado'}}.</p><p v-if="warnings[r.key]" class="reconcile-hint">{{warnings[r.key]}}</p><div class="reconcile-row-fields"><label>Operación<select v-model="r.kind" @change="invalidate(r)"><option v-for="(title,key) in kinds" :key="key" :value="key">{{title}}</option></select></label><label>Importe real PEN<input v-model="r.amount" inputmode="decimal" @change="invalidate(r)"></label><label>Código contrato fuente<input v-model="r.contractCode" @change="r.contractId='';invalidate(r)"></label><label>Contrato exacto<select :value="r.contractId" @change="match(r,($event.target as HTMLSelectElement).value)"><option value="">Seleccionar / comparar</option><option v-for="c in compared[r.key]?.candidates" :key="c.id" :value="c.id">{{c.contract_number}} · {{c.client_code}} · {{c.customer}} · {{c.service_type}}</option></select></label></div>
 <div class="reconcile-row-fields" v-if="['payment','advance','promotion','link'].includes(r.kind)"><label>Fecha real (sin inventar hora)<input v-model="r.receivedOn" type="date" @change="r.reviewed=false"></label><label>Método<select v-model="r.method" @change="r.reviewed=false"><option value="">Sin identificar</option><option value="cash">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="transfer">Transferencia</option><option value="other">Otros</option></select></label><label>Operación / recibo de origen<input v-model="r.reference" maxlength="100" @change="r.reviewed=false"></label><label>Responsable original<select v-model="r.collectorId" @change="r.reviewed=false"><option value="">Sin identificar</option><option v-for="c in context?.collectors" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div>
 <div v-if="['payment','discount','exemption'].includes(r.kind)" class="reconcile-invoice"><label>Factura / saldo verificado<select :value="r.invoiceId" @change="invoice(r,($event.target as HTMLSelectElement).value)"><option value="">Seleccionar después de comparar</option><option v-for="i in compared[r.key]?.invoices" :key="i.id" :value="i.id">{{i.invoice_number}} · {{i.period_start}} · saldo {{formatPen(i.amount_due)}} · {{i.finance_reconciled?'Conciliada':'Histórica no conciliada'}}</option></select></label><span>Mensualidad en fuente: {{r.fee?formatPen(r.fee):'No indicada'}}. No se reemplaza el importe recibido por la mensualidad.</span></div>
 <div v-if="r.kind==='promotion'" class="reconcile-promo"><p>Cuatro facturas futuras según regla 3+1 vigente. El importe debe proceder de la evidencia; no se calcula como supuesto pago.</p><label v-for="i in compared[r.key]?.invoices" :key="i.id"><input v-model="r.invoiceIds" type="checkbox" :value="i.id" @change="r.reviewed=false">{{i.period_start}} · {{formatPen(i.amount)}}</label></div>
 <div v-if="r.kind==='link'"><label>Movimiento existente vigente<select v-model="r.paymentId" @change="r.reviewed=false"><option value="">Seleccionar</option><option v-for="p in compared[r.key]?.possiblePayments.filter(p=>!p.reversed_at)" :key="p.id" :value="p.id">{{formatPen(p.amount)}} · {{p.method}} · {{p.reference}}</option></select></label></div>
 <div v-if="r.kind.startsWith('opening_')" class="reconcile-row-fields"><label>Corte verificado<input v-model="r.asOf" type="date" @change="r.reviewed=false"></label><template v-if="r.kind==='opening_debt'"><label>Cobertura desde<input v-model="r.periodStart" type="date" @change="r.reviewed=false"></label><label>Cobertura hasta<input v-model="r.periodEnd" type="date" @change="r.reviewed=false"></label><label>Vencimiento de la deuda<input v-model="r.dueOn" type="date" @change="r.reviewed=false"></label></template><p>No representa dinero recibido en este período. No se borran los registros históricos.</p></div>
 <label class="reconcile-reason">Motivo / evidencia financiera revisada<input v-model="r.reason" maxlength="500" minlength="10" placeholder="Describe la verificación sin credenciales ni datos técnicos" @change="r.reviewed=false"></label><label class="reconcile-attest"><input v-model="r.reviewed" type="checkbox">Confirmé identidad, importe, fecha y respaldo de esta operación.</label><small :class="issues(r).length?'reconcile-pending':'reconcile-valid'">{{issues(r).join(' · ')||'Verificado para revisión final del lote'}}</small></details></div><div class="finance-pagination"><span>{{rows.length}} registros · {{counts.valid}} verificados / {{counts.pending}} pendientes en página {{page}}</span><button :disabled="page===1||busy" @click="page--">Anterior</button><button :disabled="page*50>=rows.length||busy" @click="page++">Siguiente</button></div></article>
 <article class="finance-panel"><h3>3. Inicio financiero y revisión final</h3><div class="finance-filters"><label>Nombre del lote<input v-model="label" maxlength="120"></label><label>Fecha oficial aprobada<input v-model="startedOn" type="date"></label><label>Motivo del lote<input v-model="batchReason" maxlength="500" minlength="10"></label></div><p>La fecha no está impuesta. Se confirmará después de validar una muestra real. No habilita cortes ni reconexiones.</p><p v-if="!context?.canApply" class="finance-warning">Ejecución productiva bloqueada. La vista previa y el reporte funcionan sin importar datos reales.</p><button class="btn-primary" :disabled="busy||!context?.canApply||!ready.length" @click="review">Revisar lote de laboratorio</button><div v-if="reviewOpen" class="reconcile-final"><h3>Confirmación humana · {{ready.length}} operaciones</h3><p>Dinero fuente {{formatPen(importTotals(ready).cash)}} · deuda inicial {{formatPen(importTotals(ready).debt)}} · crédito inicial {{formatPen(importTotals(ready).credit)}} · descuentos {{formatPen(importTotals(ready).discount)}} · vinculados {{formatPen(importTotals(ready).linked)}}</p><p>Transacción de hasta 50 operaciones. Los pagos ya importados no vuelven a generar caja. No se sube el Excel.</p><button class="btn-secondary" :disabled="busy" @click="reviewOpen=false">Volver a revisión</button><button class="btn-primary" :disabled="busy" @click="commit">Confirmar importación sintética</button></div><div v-if="outcome" class="reconcile-result"><h3>Resultado del lote</h3><pre>{{JSON.stringify(outcome,null,2)}}</pre><p>Importes fuente y aplicados se conservan separados. No se contabilizan descuentos o aperturas como recaudación.</p></div></article></template>
 </section></template>
<style scoped>
.finance-reconciliation{min-width:0;overflow-wrap:anywhere}.finance-reconciliation .finance-panel,.reconcile-rows,.reconcile-row,.reconcile-row-fields>*,.reconcile-invoice>*{min-width:0}.finance-reconciliation input[type=file],.finance-reconciliation select{max-width:100%}.reconcile-row-head{cursor:pointer}.finance-reconciliation .finance-pagination{flex-wrap:wrap}.finance-reconciliation .finance-filters>label{max-width:100%}.finance-reconciliation .finance-filters input{max-width:100%}
.finance-reconciliation h2{font-size:17px;font-weight:650}.finance-reconciliation h3{font-size:14px;font-weight:650;margin-bottom:12px}.finance-reconciliation p{font-size:12px}.reconcile-upload{display:flex;gap:15px;align-items:center;font-size:12px}.reconcile-mapping,.reconcile-row-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.reconcile-mapping label,.reconcile-row-fields label,.reconcile-reason,.reconcile-invoice label{display:flex;flex-direction:column;gap:5px;font-size:11px;color:#60768b}.finance-reconciliation input:not([type=checkbox]):not([type=file]),.finance-reconciliation select{min-width:0;border:1px solid #dbe5ed;padding:7px 8px;border-radius:5px;background:white;color:#294359;font-size:12px}.reconcile-attest{display:flex;gap:8px;align-items:flex-start;font-size:11px;margin:14px 0}.reconcile-months{display:flex;flex-wrap:wrap;gap:12px;margin-top:15px;font-size:11px}.reconcile-rows{display:grid;gap:13px}.reconcile-row{padding:15px;border:1px solid #dce6ed;border-radius:7px}.reconcile-row-head{display:flex;gap:16px;flex-wrap:wrap;font-size:11px;margin-bottom:12px}.reconcile-row-fields{margin:9px 0}.reconcile-hint{color:#8b6e37;background:#fff9eb;padding:8px;border-radius:4px}.reconcile-invoice{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:10px 0;font-size:11px;color:#73889a}.reconcile-reason{margin:12px 0}.reconcile-pending{color:#9b7541;font-size:10px}.reconcile-valid{color:#367a5f;font-size:10px}.reconcile-progress{background:#f3f8fb;border:1px solid #dae7ef;border-radius:6px;padding:10px 12px;font-size:12px;margin-bottom:10px}.reconcile-progress .reconcile-valid,.reconcile-progress .reconcile-pending{font-size:12px;font-weight:600}.reconcile-row-head input[type=checkbox]{margin-right:2px}.reconcile-observed-group{margin-top:18px;border-top:1px solid #dce6ed;padding-top:12px}.reconcile-observed-group>summary{cursor:pointer;font-size:12px;color:#60768b}.reconcile-final,.reconcile-result{background:#f3f8fb;padding:16px;margin-top:15px;border:1px solid #dae7ef;border-radius:6px}.reconcile-result pre{max-height:260px;overflow:auto;font-size:10px}.reconcile-promo label{display:block;font-size:11px;padding:5px}@media(max-width:1000px){.reconcile-mapping,.reconcile-row-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.reconcile-mapping,.reconcile-row-fields,.reconcile-invoice{grid-template-columns:1fr}.reconcile-upload{display:block}}
</style>
